mapper.select:
SELECT u.user_sq AS userSq, u.user_id AS userId, u.user_nm AS userNm, u.user_email AS userEmail, u.user_phone_num AS userPhoneNum, u.user_birth_dt AS userBirthDt, u.user_type_cd AS userTypeCd, u.user_is_activate_yn AS userIsActivateYn, u.user_created_at_dtm AS createdAt, u.user_modified_at_dtm AS updatedAt, cc1.common_code_nm AS userTypeCdNm, cc2.common_code_nm AS genderNm, c.company_nm AS companyNm, c.company_ceo_nm AS companyCeoNm, c.company_biz_num AS companyBizNum FROM TBL_USER_M u LEFT JOIN TBL_COMMON_CODE_C cc1 ON u.user_type_cd = cc1.common_code_sq LEFT JOIN TBL_COMMON_CODE_C cc2 ON u.user_gender_cd = cc2.common_code_sq LEFT JOIN TBL_COMPANY_S c ON u.user_sq = c.user_sq WHERE 1=1
AND ( u.user_id LIKE CONCAT('%', #{searchQuery}, '%') OR u.user_nm LIKE CONCAT('%', #{searchQuery}, '%') OR u.user_email LIKE CONCAT('%', #{searchQuery}, '%') )
AND u.user_type_cd = #{userTypeCd}
AND u.user_is_activate_yn = #{userIsActivateYn}
ORDER BY u.user_created_at_dtm DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM TBL_USER_M u
WHERE 1=1

    AND (
        u.user_id LIKE CONCAT('%', #{searchQuery}, '%')
        OR u.user_nm LIKE CONCAT('%', #{searchQuery}, '%')
        OR u.user_email LIKE CONCAT('%', #{searchQuery}, '%')
    )


    AND u.user_type_cd = #{userTypeCd}


    AND u.user_is_activate_yn = #{userIsActivateYn}
